from math import gcd

def divides_pow_sub_self(n: int, a: int) -> bool:
    return (pow(a, n, n) - (a % n)) % n == 0

def carmichael_property(n: int) -> tuple[int, int]:
    bases = [b for b in range(1, n) if gcd(n, b) == 1]
    fooled = sum(1 for b in bases if pow(b, n - 1, n) == 1)
    return fooled, len(bases)

if __name__ == "__main__":
    n = 561
    assert all(divides_pow_sub_self(n, a) for a in range(-20, 50))
    fooled, total = carmichael_property(n)
    print(f"Korselt identity n | a^n - a holds for all tested a.")
    print(f"Carmichael: {fooled}/{total} coprime bases fooled -> {fooled == total}")

from typing import Dict, List

def factorize(n: int) -> Dict[int, int]:
    f: Dict[int, int] = {}; m = n; d = 2
    while d * d <= m:
        while m % d == 0:
            f[d] = f.get(d, 0) + 1; m //= d
        d += 1 if d == 2 else 2
    if m > 1: f[m] = f.get(m, 0) + 1
    return f

def is_prime(n: int) -> bool:
    return n > 1 and all(n % d for d in range(2, int(n**0.5) + 1))

def is_korselt(n: int) -> bool:
    if n <= 1 or is_prime(n): return False
    fac = factorize(n)
    if any(e > 1 for e in fac.values()): return False
    return all((n - 1) % (p - 1) == 0 for p in fac)

if __name__ == "__main__":
    carms: List[int] = [n for n in range(3, 10000, 2) if is_korselt(n)]
    print("Carmichael numbers < 10000:", carms)
    print("all odd:", all(n % 2 for n in carms))
    print("all squarefree:", all(all(e == 1 for e in factorize(n).values()) for n in carms))
    print("all >= 3 primes:", all(len(factorize(n)) >= 3 for n in carms))

